import { animate, useMotionValue } from "framer-motion";
import { useEffect } from "react";

const inactiveShadow = "0px 0px 0px rgba(0,0,0,0.8)";

/**
 * Custom hook to create a shadow that animates when a MotionValue changes from 0 to non-zero.
 * This is commonly used to visually "lift" an element when it's being dragged.
 * * @param {object} value - The MotionValue to track (e.g., drag Y position).
 * @returns {object} The boxShadow MotionValue.
 */
function useRaisedShadow(value) {
  // 1. Create a MotionValue to hold the shadow style
  const boxShadow = useMotionValue(inactiveShadow);

  useEffect(() => {
    let isActive = false;

    // 2. Subscribe to changes in the input MotionValue (e.g., drag position)
    const unsubscribe = value.onChange((latest) => {
      const wasActive = isActive;

      // Check if the value is non-zero (meaning the element is "active" or lifted)
      if (latest !== 0) {
        isActive = true;

        // If the state just changed from inactive to active, animate the shadow in
        if (isActive !== wasActive) {
          animate(boxShadow, "5px 5px 10px rgba(0,0,0,0.3)");
        }
      } else {
        // The value is zero (element is resting)
        isActive = false;

        // If the state just changed from active to inactive, animate the shadow out
        if (isActive !== wasActive) {
          animate(boxBoxShadow, inactiveShadow);
        }
      }
    });

    // 3. Cleanup function: runs when the component unmounts to prevent memory leaks
    return () => unsubscribe();
  }, [value, boxShadow]); // Dependencies: Re-run effect if 'value' or 'boxShadow' objects change

  // 4. Return the MotionValue containing the shadow style
  return boxShadow;
}

export default useRaisedShadow;
